// Button styles

// ButtonStyle returns a button style based on its state (focused or not)
func ButtonStyle(focused bool, variant string) lipgloss.Style {
	style := lipgloss.NewStyle().
		Padding(0, 2)

	if focused {
		switch variant {
		case "primary":
			return style.Bold(true).Background(ColorButtonBg).Foreground(ColorButtonFg)
		case "danger":
			return style.Bold(true).Background(ColorError).Foreground(ColorButtonFg)
		case "success":
			return style.Bold(true).Background(ColorOK).Foreground(ColorBlack)
		default:
			return style.Bold(true).Background(ColorButtonBg).Foreground(ColorButtonFg)
		}
	}

	switch variant {
	case "primary":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorButtonInactiveFg)
	case "danger":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorError)
	case "success":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorOK)
	case "secondary":
		return style.Background(ColorButtonInactiveBg).Foreground(ColorButtonInactiveFg)
	default:
		return style.Background(ColorButtonInactiveBg).Foreground(ColorPrimary)
	}
}

// RenderButton returns the rendered button with the given text
func RenderButton(text string, focused bool, variant string) string {
	return ButtonStyle(focused, variant).Render(text)
}

// RenderCheckbox returns the rendered checkbox
func RenderCheckbox(checked bool, label string, focused bool) string {
	box := IconCheckbox
//
// There were eleven, seven of them checkboxes selecting which tools to run.
// They asked the user to configure something the pipeline derives: the checks
// follow from the target and from what has already failed, so a question that
// was never worth asking is no longer asked.
const (
	fieldTarget    = 0
	fieldPort      = 1
	fieldDNSServer = 2
	fieldButton    = 3
	fieldCount     = 4
)

// problemsToken filters the table down to what is not settled.
//

// InEditMode implements FormView — true when a text input is active, so the
// router hands the key to the field rather than opening the command line.
func (m *Model) InEditMode() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.InEditMode()
	case tabInterfaces:
		// The interfaces table has a search box now, where the Topology tab it
		// replaced had no input at all. Returning false here would let a ":"
		// typed into the query open the command line instead (Rule 111).
		return m.interfacesModel.InEditMode()
	case tabForward:
		return m.forwardModel.InEditMode()
	case tabPath:
		return m.pathModel.InEditMode()
	}
	if m.filterBar.InEditMode() {
		return true
	}
	if m.state == StateInput {
		return m.focusedField == fieldTarget || m.focusedField == fieldPort || m.focusedField == fieldDNSServer
	}
	return false
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		m.pathModel.resize(msg.Width, msg.Height)
		return m, nil

	// The router's animation frame: the blink phase of the Ports dot and of the
	// two footers that show the shared activity dot, whichever tab is on screen
	// so a tab never comes back with a frozen phase.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		m.footer.SetBlinkPhase(msg.Blink)
		m.interfacesModel.footer.SetBlinkPhase(msg.Blink)
		m.pathModel.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	case "down":
		m.moveFocus(1)
		return m, nil
	case "up":
		m.moveFocus(-1)
		return m, nil
	case "enter":
		// enter runs from anywhere in the form: with three fields and one
		// button there is nothing else it could mean, and making the user walk
		// to the button first is a step that buys nothing.
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

func (m *Model) moveFocus(delta int) {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

	m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount

	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

func (m *Model) updateActiveInput(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.focusedField {
	case fieldTarget:
		m.targetInput, cmd = m.targetInput.Update(msg)
	case fieldPort:
		m.portInput, cmd = m.portInput.Update(msg)
	case fieldDNSServer:
		m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
	}
	return m, cmd
}

func (m *Model) handleKeyResults(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return m.openDetails()
	case "esc":
		// No origin view means netdiag was opened directly (the command
		// line), so esc stays inside it and resets to the form, as it
		// always has. An origin means it was opened prefilled from
		// elsewhere (status's H, §3.66), and esc returns there instead.
		if m.OriginView == "" {
			return m.resetToForm()
		}
		origin := m.OriginView
		return m, func() tea.Msg { return BackToOriginMsg{Origin: origin} }
	case "ctrl+r":
		return m.StartRun()
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "p":
		m.filterBar.SetTokenActive(problemsToken, !m.filterBar.IsTokenActive(problemsToken))
		m.rebuildChecksTable()
		return m, nil
	case keymap.Diagnose:
		return m.tracePathFromRoute()
	case keymap.New:
		// Always resets to the form, regardless of OriginView — the one way
		// to run a wholly new diagnostic without first leaving to wherever
		// this run was opened from. Found missing the day §3.66 shipped H:
		// esc alone left no way back to the form once an origin was set, and
		// re-entering netdiag through the command line landed on the same
		// frozen results with the same problem, since the cached view (and
		// its OriginView) is reused rather than rebuilt.
		return m.resetToForm()
	}
	return m, m.checksTable.Update(msg)
}

func (m *Model) handleKeyDetails(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.state = StateResults
		return m, nil
	case "up":
		m.detailsViewport.ScrollUp(1)
	case "down":
		m.detailsViewport.ScrollDown(1)
	case "pgup":
		m.detailsViewport.HalfPageUp()
	case "pgdown":
		m.detailsViewport.HalfPageDown()
	case "home":
		m.detailsViewport.GotoTop()
	case "end":
		m.detailsViewport.GotoBottom()
	}
	return m, nil
}

func (m *Model) openDetails() (*Model, tea.Cmd) {
	c, ok := m.checksTable.Selected()
	if !ok {
		return m, nil
	}
	m.selected = c
	m.state = StateDetails
	m.resizeDetailsViewport()
	m.detailsViewport.SetContent(m.renderDetailsContent(m.detailsViewport.Width()))
	m.detailsViewport.GotoTop()
	return m, nil
}

func (m *Model) resetToForm() (*Model, tea.Cmd) {
	m.state = StateInput
	m.focusedField = fieldTarget
	m.targetInput.Focus()
	m.results = netcheck.Results{}
	m.verdict = netcheck.Unknown
	m.filterBar.ClearSearch()
	m.filterBar.SetTokenActive(problemsToken, false)
	m.rebuildChecksTable()
	// Starting over severs the tie to wherever this run was opened from: the
	// next run is not "the monitor status sent here" anymore, so esc on its
	// results should not try to leave for a view this new target has nothing
	// to do with.
	m.OriginView = ""
	return m, nil
}
	case StateInput:
		return m.renderInputForm()
	case StateRunning, StateResults:
		// The table stays on screen while the pipeline runs, filling in as each
		// stage lands. A body that swaps itself for a spinner loses its header
		// and its columns (Rule 139), and here it would also throw away the
		// rows already answered.
		return m.renderChecks()
	case StateDetails:
		return m.detailsViewport.View()
	}
	return ""
}

func (m *Model) renderInputForm() string {
	var b strings.Builder

	b.WriteString(m.renderTextInputField("Target", m.targetInput, fieldTarget))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("Port", m.portInput, fieldPort))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("DNS Server", m.dnsServerInput, fieldDNSServer))
	b.WriteString("\n\n")
	b.WriteString("  " + theme.RenderButton("Run Diagnostics", m.focusedField == fieldButton, "primary"))

	return lipgloss.NewStyle().
		Padding(1).
		Background(theme.ColorBackground).
		Render(b.String())
}

func (m *Model) renderTextInputField(label string, input textinput.Model, fieldIdx int) string {
	prefix := "  "
	if m.focusedField == fieldIdx {
		prefix = theme.IconCircleSmall + " "
	}
	return theme.KeyStyle.Render(prefix+label+" "+theme.IconChevronRight+" ") + input.View()
}

// renderChecks draws the results table. An empty table — the run produced
// none, or the "problems" filter hid every one because they all passed —
// stays a table (Rule 139): its header and no rows. The Verdict header field
// already answers "did everything pass?" once there is a run to summarise.
func (m *Model) renderChecks() string {
	return m.checksTable.View()
}
package netdiag

import (
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// GetTitle implements HeaderView
func (m *Model) GetTitle() string {
	base := theme.IconNetwork + " Network"
	if m.state == StateDetails {
		if label := m.selected.Title; label != "" {
			detailStyle := lipgloss.NewStyle().Foreground(theme.ColorPrimary).Background(theme.ColorBackground)
			return base + detailStyle.Render(" "+theme.IconChevronRight+" "+label)
		}
	}
	return base
}

// GetIcon implements HeaderView
func (m *Model) GetIcon() string {
	return theme.IconNetwork
}

// GetShortcuts implements HeaderView
func (m *Model) GetShortcuts() shortcut.Shortcuts {
	tabShortcuts := shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
	}

	if m.activeTab == tabPath {
		return m.pathModel.shortcuts()
	}

	if m.activeTab == tabInterfaces {
		// A read in flight greys the table's keys rather than removing them:
		// the tab is the same screen either side of a refresh, and a column
		// that empties and refills on every ctrl+r is the flicker Rule 130 is
		// about. ctrl+r stays lit — asking again is exactly what still applies.
		loading := m.interfacesModel.loading
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: "ctrl+r", Description: "Refresh"},
			{Key: "/", Description: "Filter", Disabled: loading},
			{Key: ".", Description: "Sort", Disabled: loading},
			{Key: "?", Description: "Help"},
		}...)
	}

	if m.activeTab == tabForward {
		if m.forwardModel.form != nil {
			// A form is a mode, so the whole list is replaced rather than
			// greyed (Rule 130): greying N and K here would show the union of
			// two vocabularies.
			return shortcut.Shortcuts{
				// ←→ only cycles the type, so it greys elsewhere (Rule 130).
				{Key: "←→", Description: "Change type", Disabled: !m.forwardModel.form.TypeFocused()},
				{Key: "enter", Description: "Open the forward"},
				{Key: "esc", Description: "Cancel"},
			}
		}
		if m.forwardModel.table.FilterBar().InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: keymap.New, Description: "New forward"},
			// Nothing to pause, resume or delete on an empty table (Rule 130).
			{Key: "space", Description: m.forwardModel.toggleLabel(), Disabled: !m.forwardModel.switchable().Enabled()},
			{Key: keymap.Kill, Description: "Delete forward", Disabled: !m.forwardModel.closable().Enabled()},
			{Key: "/", Description: "Search"},
			{Key: ".", Description: "Sort"},
			{Key: "?", Description: "Help"},
		}...)
	}

	if m.activeTab == tabPorts {
		if m.portsModel.table.FilterBar().InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		sc := shortcut.Shortcuts{
			{Key: "t", Description: "Toggle TCP"},
			{Key: "u", Description: "Toggle UDP"},
			{Key: "l", Description: "Toggle LISTEN"},
			{Key: "e", Description: "Toggle ESTAB"},
			{Key: "n", Description: "Toggle numeric"},
			{Key: "z", Description: "Reset filters"},
			{Key: "/", Description: "Search"},
			{Key: "space", Description: "Pause/Resume"},
			// A socket the system declines to attribute carries no PID, so
			// there is nothing to signal (Rule 130).
			{Key: keymap.Kill, Description: "Kill process", Disabled: !m.portsModel.killable().Enabled()},
			{Key: "?", Description: "Help"},
		}
		return append(tabShortcuts, sc...)
	}

	switch m.state {
	case StateInput:
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: "enter", Description: "Run the checks"},
			{Key: "?", Description: "Help"},
		}...)
	case StateRunning:
		return shortcut.Shortcuts{
			{Key: "esc", Description: "Cancel and keep what completed"},
		}
	case StateResults:
		if m.filterBar.InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		sc := shortcut.Shortcuts{
			{Key: "enter", Description: "Explain the check"},
		}
		label := "Show problems only"
		if m.filterBar.IsTokenActive(problemsToken) {
			label = "Show every check"
		}
		escLabel := "New diagnostic"
		if m.OriginView != "" {
			escLabel = "Go back"
		}
		sc = append(sc,
			shortcut.Shortcut{Key: "p", Description: label},
			shortcut.Shortcut{Key: "/", Description: "Search"},
			shortcut.Shortcut{Key: keymap.Diagnose, Description: "Trace the path", Disabled: !m.pathFromRoute().Enabled()},
			shortcut.Shortcut{Key: "ctrl+r", Description: "Run again"},
			shortcut.Shortcut{Key: "esc", Description: escLabel},
		)
		if m.OriginView != "" {
			// Otherwise esc already reads "New diagnostic" and does exactly
			// this — advertising both here would just say the same thing
			// twice (Rule 138). With an origin, esc means "go back" instead,
			// so this is the only key left that starts a fresh target.
			sc = append(sc, shortcut.Shortcut{Key: keymap.New, Description: "New diagnostic"})
		}
		sc = append(sc, shortcut.Shortcut{Key: "?", Description: "Help"})
		return append(tabShortcuts, sc...)
	case StateDetails:
		return shortcut.Shortcuts{
			{Key: "esc", Description: "Go back to the checks"},
		}
	}
	return tabShortcuts
}

// GetHeaderInfo implements HeaderView.
//
// The verdict is the one line worth spending: it is the answer to the question
// the view exists for, and reading it off ten rows is what the header is
// supposed to save. It appears only once there is a run to summarise.
func (m *Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
	if m.activeTab == tabPath {
		return append(info, m.pathModel.headerInfo()...)
	}
	if m.activeTab == tabInterfaces {
		return append(info, shortcut.HeaderInfo{
			Key:   "Interfaces",
			Value: m.interfacesModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab == tabPorts {
		return append(info, shortcut.HeaderInfo{
			Key:   "Ports",
			Value: m.portsModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab == tabForward {
		return append(info, shortcut.HeaderInfo{
			Key:   "Forwards",
			Value: m.forwardModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab != tabDiagnostics || m.state == StateInput {
		return info
	}
	if len(m.results.All()) == 0 {
		return info
	}
	return append(info, shortcut.HeaderInfo{
		Key:   "Verdict",
		Value: m.verdict.String(),
		Style: verdictHeaderStyle(m.verdict),
	})
}

// verdictHeaderStyle colours the headline the way the table colours a cell.
func verdictHeaderStyle(v netcheck.Verdict) lipgloss.Style {
	switch v {
	case netcheck.Fail:
		return theme.SeverityTextStyle("CRITICAL")
	case netcheck.Warn:
		return theme.SeverityTextStyle("MEDIUM")
	case netcheck.OK:
		return theme.StatusOKStyle
	default:
		return theme.DimStyle
	}
}

// pathFooterHeight is the Path footer in every state: the target bar (2), the
// tab row, a blank line and the info line (Rule 124).
const pathFooterHeight = 5

// GetFooterHeight implements FooterView — tab bar + empty + info + ports filter bar when visible (Rule 124)
func (m *Model) GetFooterHeight() int {
	if m.activeTab == tabPath {
		return pathFooterHeight
	}
	if m.activeTab == tabPorts {
		return 3 + m.portsModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabDiagnostics {
		return 3 + m.filterBar.ExtraHeight()
	}
	if m.activeTab == tabInterfaces {
		return 3 + m.interfacesModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabForward {
		return 3 + m.forwardModel.table.FilterBar().ExtraHeight()
	}
	return 3
}

// RenderFooter implements FooterView
func (m *Model) RenderFooter(width int) string {
	var parts []string

	// The active tab's filter bar renders above the tab bar when visible; on
	// Path the target field takes that slot in every state.
	switch {
	case m.activeTab == tabPath:
		parts = append(parts, m.pathModel.barView(width))
	case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
		parts = append(parts, m.portsModel.table.FilterBar().View())
	case m.activeTab == tabDiagnostics && m.filterBar.IsVisible():
		parts = append(parts, m.filterBar.View())
	case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
		parts = append(parts, m.interfacesModel.table.FilterBar().View())
	case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
		parts = append(parts, m.forwardModel.table.FilterBar().View())
	}

	tabs := theme.RenderTabs([]theme.TabItem{
		{Label: "Diagnostics"},
		{Label: "Ports"},
		{Label: "Interfaces"},
		{Label: "Forward"},
		{Label: "Path"},
	}, m.activeTab)
	tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)

	// The message belongs to the tab that raised it: each sub-model keeps its
	// own, so switching away does not carry one tab's notice onto another.
	footer, status := m.activeFooter()
	parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
	return strings.Join(parts, "\n")
}

// activeFooter resolves the message line of whichever tab is on screen, and the
// status that tab derives on every frame.
func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
	switch m.activeTab {
	case tabPorts:
		return &m.portsModel.footer, m.portsModel.statusLine()
	case tabInterfaces:
		return &m.interfacesModel.footer, m.interfacesModel.statusLine()
	case tabForward:
		return &m.forwardModel.footer, m.forwardModel.status()
	case tabPath:
		return &m.pathModel.footer, m.pathModel.statusLine()
	}
	return &m.footer, m.statusLine()
}

// statusLine is what the diagnostics tab derives on every frame: a progress
// label while the pipeline walks, and nothing once it has an answer. It is a
// status rather than a footer message because it is a state, not an event —
// a message expires after three seconds and a run outlives that (Rule 128).
func (m *Model) statusLine() components.Status {
	if m.state == StateRunning {
		return components.Status{Text: m.progressLabel(), Activity: true}
	}
	return components.Status{}
}

